// Pure mathematical & electromechanical model for:
// Fig 01 — Q-Lock Modular Smart-Pylon & Control-Surface HIL Test Bench

const DELTA_MIN = -30;
const DELTA_MAX = 30;
const HIL_LATENCY_MS = 0.42;
const GAUGE_MAX_NM = 20;

const PAYLOAD_MODES = [
  {
    index: 0,
    id: "S1-LIDAR",
    tag: "0: S1-LIDAR",
    busPowerW: 180,
    preloadShare: 0.22,
    preloadMm: 1.4,
    knobDeg: -42,
    descTr: "S1-LIDAR · Optik Haritalama Podu",
    descEn: "S1-LIDAR · Optical Mapping Pod",
  },
  {
    index: 1,
    id: "B2-AGRO",
    tag: "1: B2-AGRO",
    busPowerW: 640,
    preloadShare: 0.90,
    preloadMm: 4.2,
    knobDeg: 0,
    descTr: "B2-AGRO · Yüksek Debili Görev Podu",
    descEn: "B2-AGRO · High-Flow Mission Pod",
  },
  {
    index: 2,
    id: "A2-UCAV",
    tag: "2: A2-UCAV",
    busPowerW: 420,
    preloadShare: 0.56,
    preloadMm: 2.8,
    knobDeg: 42,
    descTr: "A2-UCAV · Taktik Akıllı Pilon Yükü",
    descEn: "A2-UCAV · Tactical Smart-Pylon Store",
  },
];

function clamp(value, low, high) {
  return Math.min(high, Math.max(low, value));
}

function computeRigState(deltaDeg = 0, modeIndex = 0) {
  const delta = clamp(Number(deltaDeg) || 0, DELTA_MIN, DELTA_MAX);
  const absDelta = Math.abs(delta);
  const idx = ((Math.round(modeIndex) % PAYLOAD_MODES.length) + PAYLOAD_MODES.length) % PAYLOAD_MODES.length;
  const mode = PAYLOAD_MODES[idx];

  // Exact physics equations from specification:
  // Hinge moment: M_h = 0.48 * |deltaDeg| + 1.6 (N·m)
  // Bus current:  I_bus = 2.4 + 0.38 * |deltaDeg| (A)
  // Deterministic HIL loop latency: 0.42 ms
  const hingeMomentNm = 0.48 * absDelta + 1.6;
  const busCurrentA = 2.4 + 0.38 * absDelta;
  const latencyMs = HIL_LATENCY_MS;
  const busPowerW = mode.busPowerW;

  // Mechanical kinematics in world units (1 unit ≈ 1 mm scaled bench geometry)
  const carriageDx = -(delta / 30) * 10.5;
  const plungerDx = ((hingeMomentNm - 1.6) / (16.0 - 1.6)) * 2.4;
  const preloadShift = mode.preloadShare * 3.2;

  // Dial torque gauge angle (0..20 N·m mapped over a 276° precision scale, -138° to +138°)
  const gaugeFraction = clamp(hingeMomentNm / GAUGE_MAX_NM, 0, 1);
  const gaugeAngleRad = ((-138 + gaugeFraction * 276) * Math.PI) / 180;

  return {
    deltaDeg: delta,
    modeIndex: idx,
    mode,
    hingeMomentNm,
    busCurrentA,
    busPowerW,
    latencyMs,
    carriageDx,
    plungerDx,
    preloadShift,
    gaugeFraction,
    gaugeAngleRad,
  };
}

function formatReadout(state, lang = "tr") {
  const sign = state.deltaDeg >= 0 ? "+" : "−";
  const dStr = `${sign}${Math.abs(state.deltaDeg).toFixed(1)}°`;
  const mhStr = `${state.hingeMomentNm.toFixed(2)} N·m`;
  const iStr = `${state.busCurrentA.toFixed(2)} A`;
  const pStr = `${state.busPowerW} W`;
  const latStr = `${state.latencyMs.toFixed(2)} ms`;
  if (lang === "en") {
    return `${state.mode.id} · ${dStr} · ${mhStr} · ${iStr} · ${pStr} · ${latStr}`;
  }
  return `${state.mode.id} · ${dStr} · ${mhStr} · ${iStr} · ${pStr} · ${latStr}`;
}

// Shared dynamic part geometry builders for build-time (rest pose + audit)
// and browser runtime (60 fps interactive motion).

const FLAP_POLY = [
  [2.3, -2.5],
  [6.5, -3.0],
  [18.0, -2.0],
  [33.5, -0.6],
  [33.5, 0.6],
  [18.0, 2.2],
  [6.5, 3.2],
  [2.3, 2.5],
];

const HORN_POLY = [
  [7.2, -2.6],
  [12.4, -2.1],
  [10.9, -6.8],
  [8.7, -6.8],
];

function makeParts(k, G, P, CFG) {
  const S = (paths, style) => k.solidSvg(paths, style);
  const Ln = (d, style) => k.lineSvg(d, style);

  function flapBasis(deltaDeg = 0) {
    const rad = (deltaDeg * Math.PI) / 180;
    const c = Math.cos(rad);
    const s = Math.sin(rad);
    const eChord = [c, 0, -s];
    const eThick = [s, 0, c];
    const origin = [CFG.hingeX, 0, CFG.hingeZ];
    const F = G.frameOf(origin, [0, 1, 0], eChord, eThick);
    const pt = (u, v, y) => [
      origin[0] + eChord[0] * u + eThick[0] * v,
      y,
      origin[2] + eChord[2] * u + eThick[2] * v,
    ];
    return { F, eChord, eThick, pt };
  }

  function hornPin(deltaDeg = 0) {
    const { pt } = flapBasis(deltaDeg);
    return pt(9.8, -8.8, CFG.hornY);
  }

  function carriagePin(carriageDx = 0) {
    return [CFG.carRestX + carriageDx - 6.0, CFG.carClevisY, CFG.carClevisZ];
  }

  function flapSvg(deltaDeg = 0) {
    const { F, pt } = flapBasis(deltaDeg);
    const out = [];
    // Control horn clevis under near-side of flap (drawn first as it sits below/behind upper skin)
    out.push(S(G.prismOf(F, HORN_POLY, CFG.hornY - 1.4, CFG.hornY + 1.4, P), { tone: "mid" }));
    const hPin = hornPin(deltaDeg);
    out.push(S(G.sphereOf(hPin, 2.0, P, { steps: 32 }), { tone: "hi" }));

    // Main carbon-composite control-surface coupon blade
    const ribPts = [
      [2.3, 2.5],
      [6.5, 3.2],
      [18.0, 2.2],
      [33.5, 0.6],
    ];
    const ribsD = [-21, -11, -1]
      .map((y) => k.pathOf(ribPts.map(([u, v]) => k.iso(pt(u, v, y), P))))
      .join("");
    out.push(
      S(G.prismOf(F, FLAP_POLY, CFG.flapY0, CFG.flapY1, P), {
        tone: "hi",
        crease: "lo",
        inner: Ln(ribsD, { tone: "faint" }),
      }),
    );

    // Machined aluminum outboard tip rib cap on +y end
    out.push(S(G.prismOf(F, FLAP_POLY, CFG.flapY1, CFG.flapY1 + 1.5, P), { tone: "mid" }));
    return out.join("");
  }

  function pushrodSvg(deltaDeg = 0, carriageDx = 0) {
    const p0 = carriagePin(carriageDx);
    const p1 = hornPin(deltaDeg);
    const diff = G.sub3(p1, p0);
    const L = G.len3(diff);
    const dir = G.unit3(diff);
    const F = G.frameAlong(p0, dir);
    const rRod = 1.05;
    const rBall = 2.0;
    const trim = Math.sqrt(rBall * rBall - rRod * rRod);
    const sMid0 = L * 0.41;
    const sMid1 = L * 0.59;
    const out = [];
    out.push(S(G.sphereOf(p0, rBall, P, { steps: 32 }), { tone: "hi" }));
    out.push(S(G.disc(trim, sMid0, rRod, F, P, { steps: 20 }), { tone: "hi" }));
    out.push(
      S(G.disc(sMid0, sMid1, 1.65, F, P, { steps: 24 }), {
        tone: "mid",
        inner: Ln(G.arcOf(F, (sMid0 + sMid1) / 2, 1.65, P), { tone: "faint" }),
      }),
    );
    out.push(S(G.disc(sMid1, L - trim, rRod, F, P, { steps: 20 }), { tone: "hi" }));
    return out.join("");
  }

  function qlockLatchSvg(latchShare = 0) {
    // THE single `lit` accent assembly: Q-Lock sliding locking pin + eccentric cam lever!
    const slideY = latchShare * 2.8;
    const pinBase = CFG.qlockPinBase; // [-89, 4.4, 66]
    const pinLen = 5.6 + slideY;
    const YF = G.frameOf(pinBase, [0, 1, 0], [1, 0, 0], [0, 0, 1]);
    const camY = pinBase[1] + pinLen;
    const XF = G.frameOf([pinBase[0] - 4.4, camY, pinBase[2]], [1, 0, 0], [0, 1, 0], [0, 0, 1]);

    // Cam lever projects across screen (-x, +y, +z) from cylindrical cam wall in strict back-to-front order
    const ang = ((24 + latchShare * 38) * Math.PI) / 180;
    const lDir = G.unit3([-0.58, 0.58, Math.sin(ang) * 0.75]);
    const leverOrigin = [pinBase[0] - 0.6, camY, pinBase[2]];
    const LF = G.frameAlong(leverOrigin, lDir);
    const sExit = Math.sqrt(2.85 * 2.85 - 1.15 * 1.15) / Math.hypot(lDir[1], lDir[2]);

    const out = [];
    // Sliding ground locking pin
    out.push(
      S(G.disc(0, pinLen, 2.05, YF, P, { steps: 28 }), {
        tone: "hi",
        lit: true,
        inner: Ln(G.arcOf(YF, pinLen * 0.5, 2.05, P), { tone: "lo" }),
      }),
    );
    // Eccentric cam barrel
    out.push(
      S(G.disc(0, 8.8, 2.85, XF, P, { steps: 32, bevel: 0.35 }), {
        tone: "hi",
        lit: true,
        inner: Ln(G.arcOf(XF, 4.4, 2.85, P), { tone: "lo" }),
      }),
    );
    // Cam release lever stem + contoured handle grip barrel
    out.push(S(G.disc(sExit, 10.8, 1.15, LF, P, { steps: 20 }), { tone: "hi", lit: true }));
    out.push(
      S(G.disc(10.8, 17.0, 1.9, LF, P, { steps: 26, bevel: 0.3 }), {
        tone: "hi",
        lit: true,
        inner: Ln(G.arcOf(LF, 13.9, 1.9, P), { tone: "lo" }),
      }),
    );
    return out.join("");
  }

  function pylonSpring(preloadShift = 0) {
    const zFrom = CFG.pylonSpringZ0 + preloadShift;
    const zTo = CFG.pylonSpringZ1;
    const [cx, cy] = CFG.pylonCenter;
    const radius = 3.8;
    const turns = 5;
    const count = turns * 18;
    const back = [];
    const front = [];
    let run = [];
    let near = null;
    for (let i = 0; i <= count; i++) {
      const share = i / count;
      const angle = share * turns * Math.PI * 2;
      const u = radius * Math.cos(angle);
      const v = radius * Math.sin(angle);
      const z = zFrom + (zTo - zFrom) * share;
      const facing = k.depthOf([Math.cos(angle), Math.sin(angle), 0], P) > 0;
      const flat = k.iso([cx + u, cy + v, z], P);
      if (near === null) near = facing;
      if (facing !== near) {
        run.push(flat);
        (near ? front : back).push(k.pathOf(run));
        run = [flat];
        near = facing;
        continue;
      }
      run.push(flat);
    }
    if (run.length > 1) (near ? front : back).push(k.pathOf(run));
    return { back: back.join(""), front: front.join("") };
  }

  function loadSpring(carriageDx = 0, preloadShift = 0) {
    const fromX = CFG.carRestX + carriageDx + 11.0;
    const toX = CFG.collarBaseX - preloadShift;
    return k.coil(fromX, toX, [CFG.rodY, CFG.rodZ], 4.2, 7, "x", P);
  }

  function dialNeedleD(angleRad = 0) {
    const [cx, cy] = CFG.dialCenter;
    const tail = 3.6;
    const tip = CFG.dialR - 3.8;
    return k.lineOnTop(
      [cx - Math.sin(angleRad) * tail, cy + Math.cos(angleRad) * tail],
      [cx + Math.sin(angleRad) * tip, cy - Math.cos(angleRad) * tip],
      CFG.dialTop + 0.2,
      P,
    );
  }

  function modePointerD(knobDeg = -42) {
    const rad = (knobDeg * Math.PI) / 180;
    const [cx, cy] = CFG.knobCenter;
    return k.lineOnTop(
      [cx - Math.sin(rad) * 1.2, cy + Math.cos(rad) * 1.2],
      [cx + Math.sin(rad) * 5.0, cy - Math.cos(rad) * 5.0],
      CFG.knobTop + 0.15,
      P,
    );
  }

  function fcWaveSvg(deltaDeg = 0, modeIndex = 0, phase = 0) {
    // Local coordinates in FC-400 screen plane: x in [-15, 15], y in [-5.5, 5.5]
    const amp = 1.2 + (Math.abs(deltaDeg) / 30) * 3.1;
    const sign = deltaDeg >= 0 ? 1 : -1;
    const pts = [];
    const N = 24;
    for (let i = 0; i <= N; i++) {
      const u = i / N;
      const x = -14.2 + u * 19.4;
      const y = -sign * amp * Math.sin(u * Math.PI * 2.2 + phase) * (0.55 + 0.45 * Math.sin(u * Math.PI));
      pts.push([x, y]);
    }
    const pBarH = modeIndex === 1 ? 8.6 : modeIndex === 2 ? 5.8 : 2.8;
    const mBarH = 1.6 + (Math.abs(deltaDeg) / 30) * 7.0;
    const bars = [
      `M8.2 4.4V${(4.4 - mBarH).toFixed(2)}`,
      `M11.0 4.4V${(4.4 - pBarH).toFixed(2)}`,
      `M13.8 4.4V1.2`,
    ].join("");
    const grid = `M-14.2 0H5.4M-14.2 -3.6H5.4M-14.2 3.6H5.4`;
    return (
      `<path class="iso-line" data-tone="faint" data-free="" d="${grid}"/>` +
      `<path class="iso-line" data-tone="hi" data-free="" d="${k.pathOf(pts)}"/>` +
      `<path class="iso-line" data-tone="mid" data-free="" style="stroke-width:1.15" d="${bars}"/>`
    );
  }

  return {
    flapBasis,
    hornPin,
    carriagePin,
    flapSvg,
    pushrodSvg,
    qlockLatchSvg,
    pylonSpring,
    loadSpring,
    dialNeedleD,
    modePointerD,
    fcWaveSvg,
  };
}


