function createHilController(rootEl, initialOpts = {}) {
  let lang = initialOpts.lang === "en" ? "en" : "tr";
  let theme = initialOpts.theme === "dark" ? "dark" : "light";
  rootEl.classList.add("iso", "hil-anatomy-root");
  rootEl.setAttribute("data-theme", theme);
  rootEl.setAttribute("lang", lang);

  const initState = computeRigState(0, 0);
  const copy0 = RIG_COPY[lang];

  const controlsHtml = `
    <div class="hil-controls" data-hil-controls>
      <div class="hil-mode-group" role="group" aria-label="Payload mode selector">
        <span class="hil-ctrl-label" data-label-mode>${copy0.modeLabel}</span>
        ${PAYLOAD_MODES.map((m, idx) => `<button type="button" class="hil-mode-btn" data-mode-btn="${idx}" aria-pressed="${idx === 0 ? "true" : "false"}">${m.id} · ${m.busPowerW}W</button>`).join("")}
      </div>
      <label class="hil-scrub-group">
        <span class="hil-ctrl-label" data-label-delta>${copy0.deltaLabel}</span>
        <input type="range" class="hil-scrub-slider" data-delta-slider min="-30" max="30" step="0.5" value="0" />
        <span class="hil-scrub-val" data-delta-val>+0.0°</span>
      </label>
    </div>`;

  rootEl.innerHTML = kKit.plateHtml({
    fig: copy0.fig,
    title: copy0.title,
    hint: copy0.hint,
    readout: formatReadout(initState, lang),
    keys: copy0.keys,
    caption: copy0.caption,
    body: `<div class="iso-stage" tabindex="0" role="slider" aria-label="${copy0.title}" aria-valuemin="-30" aria-valuemax="30" aria-valuenow="0">${RIG_SVG}</div>`,
  });

  const plateEl = rootEl.querySelector(".iso-plate");
  plateEl.insertAdjacentHTML("afterend", controlsHtml);

  const stage = rootEl.querySelector(".iso-stage");
  const svg = stage.querySelector("svg");
  const flapEl = svg.querySelector('[data-part="flap"]');
  const pushrodEl = svg.querySelector('[data-part="pushrod"]');
  const carriageEl = svg.querySelector('[data-part="carriage"]');
  const rodLeftEl = svg.querySelector('[data-part="rod-left"]');
  const rodRightEl = svg.querySelector('[data-part="rod-right"]');
  const springBackEl = svg.querySelector('[data-part="spring-back"]');
  const springFrontEl = svg.querySelector('[data-part="spring-front"]');
  const springCollarEl = svg.querySelector('[data-part="spring-collar"]');
  const qlockLitEl = svg.querySelector('[data-part="qlock-lit"]');
  const pylonSpringBackEl = svg.querySelector('[data-part="pylon-spring-back"]');
  const pylonSpringFrontEl = svg.querySelector('[data-part="pylon-spring-front"]');
  const pylonStoreEl = svg.querySelector('[data-part="pylon-store"]');
  const needleEl = svg.querySelector('[data-part="needle"]');
  const modePtrEl = svg.querySelector('[data-part="mode-pointer"]');
  const fcWaveEl = svg.querySelector('[data-part="fc-wave"]');

  const figCorner = rootEl.querySelector('[data-corner="fig"]');
  const titleCorner = rootEl.querySelector('[data-corner="title"]');
  const hintCorner = rootEl.querySelector('[data-corner="hint"]');
  const readoutCorner = rootEl.querySelector('[data-readout]');
  const captionEl = rootEl.querySelector(".iso-legend > p, .iso-caption");
  const keyEls = [...rootEl.querySelectorAll(".iso-key")];
  const modeBtns = [...rootEl.querySelectorAll("[data-mode-btn]")];
  const sliderEl = rootEl.querySelector("[data-delta-slider]");
  const deltaValEl = rootEl.querySelector("[data-delta-val]");
  const labelModeEl = rootEl.querySelector("[data-label-mode]");
  const labelDeltaEl = rootEl.querySelector("[data-label-delta]");

  const parts = makeParts(kKit, GKit, RIG_P, RIG_CFG);
  const ROD_F = GKit.frameOf([0, RIG_CFG.rodY, RIG_CFG.rodZ], [1, 0, 0], [0, 1, 0], [0, 0, 1]);
  const still = matchMedia("(prefers-reduced-motion: reduce)");

  let targetDelta = 0;
  let curDelta = 0;
  let deltaVel = 0;

  let modeIdx = 0;
  let curPreload = initState.preloadShift;
  let preloadVel = 0;
  let curKnobDeg = initState.mode.knobDeg;
  let knobVel = 0;
  let latchPulse = 0; // 0..1..0 unlatch/relock envelope on mode switch
  let latchAge = 99;

  let needleAng = initState.gaugeAngleRad;
  let needleVel = 0;
  let wavePhase = 0;

  let touring = !still.matches;
  let visible = true;
  let frame = 0;
  let lastTime = 0;
  let tourClock = 0;
  let idleTimer = 0;
  let dragging = false;

  const TOUR_STOPS = [18, -22, 27, 0, -15, 24];

  function renderFrame() {
    const st = computeRigState(curDelta, modeIdx);
    const dx = st.carriageDx;

    flapEl.innerHTML = parts.flapSvg(curDelta);
    pushrodEl.innerHTML = parts.pushrodSvg(curDelta, dx);
    carriageEl.setAttribute("transform", kKit.translateAlong(RIG_P, [dx, 0, 0]));

    const carLeft = -43 + dx;
    const carRight = -21 + dx;
    const collarLeft = RIG_CFG.collarBaseX - curPreload;
    rodLeftEl.innerHTML = kKit.solidSvg(GKit.disc(-58, carLeft, 1.65, ROD_F, RIG_P, { steps: 20 }), { tone: "mid" });
    rodRightEl.innerHTML = kKit.solidSvg(GKit.disc(carRight, collarLeft, 1.65, ROD_F, RIG_P, { steps: 20 }), { tone: "mid" });

    const sp = parts.loadSpring(dx, curPreload);
    springBackEl.setAttribute("d", sp.back);
    springFrontEl.setAttribute("d", sp.front);
    springCollarEl.setAttribute("transform", kKit.translateAlong(RIG_P, [-curPreload, 0, 0]));

    qlockLitEl.innerHTML = parts.qlockLatchSvg(latchPulse);
    const pSp = parts.pylonSpring(curPreload);
    pylonSpringBackEl.setAttribute("d", pSp.back);
    pylonSpringFrontEl.setAttribute("d", pSp.front);
    pylonStoreEl.setAttribute("transform", kKit.translateAlong(RIG_P, [0, 0, curPreload]));

    needleEl.setAttribute("d", parts.dialNeedleD(needleAng));
    modePtrEl.setAttribute("d", parts.modePointerD(curKnobDeg));
    fcWaveEl.innerHTML = parts.fcWaveSvg(curDelta, modeIdx, wavePhase);

    const rText = formatReadout(st, lang);
    if (readoutCorner && readoutCorner.textContent !== rText) readoutCorner.textContent = rText;

    const sign = curDelta >= 0 ? "+" : "−";
    const dShort = sign + Math.abs(curDelta).toFixed(1) + "°";
    if (deltaValEl && deltaValEl.textContent !== dShort) deltaValEl.textContent = dShort;
    if (sliderEl && document.activeElement !== sliderEl) sliderEl.value = String(Math.round(curDelta * 2) / 2);

    stage.setAttribute("aria-valuenow", curDelta.toFixed(1));
    stage.setAttribute("aria-valuetext", rText);
  }

  function stepSpring(val, vel, target, stiff, damp, dt) {
    let x = val, v = vel;
    const sub = 4, h = dt / sub;
    for (let i = 0; i < sub; i++) {
      v += ((target - x) * stiff - v * damp) * h;
      x += v * h;
    }
    if (Math.abs(target - x) < 0.004 && Math.abs(v) < 0.004) {
      return [target, 0, true];
    }
    return [x, v, false];
  }

  function tick(now) {
    const dt = lastTime ? Math.min((now - lastTime) / 1000, 1 / 24) : 1 / 60;
    lastTime = now;
    const calm = still.matches;

    if (touring && !calm) {
      tourClock += dt;
      const slot = Math.floor(tourClock / 2.6);
      targetDelta = TOUR_STOPS[slot % TOUR_STOPS.length];
      const nextMode = Math.floor(tourClock / 7.8) % PAYLOAD_MODES.length;
      if (nextMode !== modeIdx) selectMode(nextMode, true);
    }

    const wantState = computeRigState(targetDelta, modeIdx);
    let s1 = true, s2 = true, s3 = true, s4 = true;

    if (calm) {
      curDelta = targetDelta; deltaVel = 0;
      curPreload = wantState.preloadShift; preloadVel = 0;
      curKnobDeg = wantState.mode.knobDeg; knobVel = 0;
      needleAng = wantState.gaugeAngleRad; needleVel = 0;
      latchPulse = 0;
    } else {
      [curDelta, deltaVel, s1] = stepSpring(curDelta, deltaVel, targetDelta, 190, 24, dt);
      [curPreload, preloadVel, s2] = stepSpring(curPreload, preloadVel, wantState.preloadShift, 260, 26, dt);
      [curKnobDeg, knobVel, s3] = stepSpring(curKnobDeg, knobVel, wantState.mode.knobDeg, 320, 28, dt);

      const liveMoment = computeRigState(curDelta, modeIdx).gaugeAngleRad;
      [needleAng, needleVel, s4] = stepSpring(needleAng, needleVel, liveMoment, 340, 26, dt);

      if (latchAge < 0.65) {
        latchAge += dt;
        const u = Math.min(1, latchAge / 0.65);
        latchPulse = Math.sin(u * Math.PI);
        s2 = false;
      } else {
        latchPulse = 0;
      }
      wavePhase = (wavePhase + dt * (2.6 + Math.abs(curDelta) * 0.08)) % (Math.PI * 2);
    }

    renderFrame();
    const settled = !touring && s1 && s2 && s3 && s4 && latchPulse === 0;
    frame = visible && !settled ? requestAnimationFrame(tick) : 0;
  }

  function kick() {
    if (!frame && visible) {
      lastTime = 0;
      frame = requestAnimationFrame(tick);
    }
  }

  function pauseTourAndSchedule() {
    touring = false;
    clearTimeout(idleTimer);
    idleTimer = setTimeout(() => {
      if (!still.matches && !dragging) {
        touring = true;
        kick();
      }
    }, 4200);
  }

  function steerDelta(deg) {
    pauseTourAndSchedule();
    targetDelta = clamp(deg, DELTA_MIN, DELTA_MAX);
    kick();
  }

  function selectMode(nextIdx, fromTour = false) {
    const clean = ((nextIdx % PAYLOAD_MODES.length) + PAYLOAD_MODES.length) % PAYLOAD_MODES.length;
    if (!fromTour) pauseTourAndSchedule();
    if (clean !== modeIdx) {
      modeIdx = clean;
      latchAge = 0;
    }
    modeBtns.forEach((btn, idx) => btn.setAttribute("aria-pressed", idx === modeIdx ? "true" : "false"));
    kick();
  }

  function applyLang(nextLang) {
    lang = nextLang === "en" ? "en" : "tr";
    rootEl.setAttribute("lang", lang);
    const c = RIG_COPY[lang];
    if (figCorner) figCorner.textContent = c.fig;
    if (titleCorner) titleCorner.textContent = c.title;
    if (hintCorner) hintCorner.textContent = c.hint;
    if (labelModeEl) labelModeEl.textContent = c.modeLabel;
    if (labelDeltaEl) labelDeltaEl.textContent = c.deltaLabel;
    stage.setAttribute("aria-label", c.title);
    keyEls.forEach((el, idx) => {
      const sw = el.querySelector("svg");
      if (c.keys[idx] && sw) {
        el.innerHTML = "";
        el.appendChild(sw);
        el.append(" " + c.keys[idx].label);
      }
    });
    const capNode = rootEl.querySelector(".iso-caption");
    if (capNode) capNode.textContent = c.caption;
    renderFrame();
  }

  function applyTheme(nextTheme) {
    theme = nextTheme === "dark" ? "dark" : "light";
    rootEl.setAttribute("data-theme", theme);
  }

  const pointerToDelta = (clientX) => {
    const box = svg.getBoundingClientRect();
    const share = clamp(((clientX - box.left) / Math.max(1, box.width) - 0.12) / 0.76, 0, 1);
    return DELTA_MIN + share * (DELTA_MAX - DELTA_MIN);
  };

  const onPointerMove = (e) => {
    if (e.pointerType === "touch" && !dragging) return;
    steerDelta(pointerToDelta(e.clientX));
  };
  const onPointerDown = (e) => {
    dragging = true;
    stage.setPointerCapture?.(e.pointerId);
    steerDelta(pointerToDelta(e.clientX));
  };
  const onPointerUp = () => {
    dragging = false;
    pauseTourAndSchedule();
  };
  const onKeyDown = (e) => {
    if (e.key === "ArrowRight" || e.key === "ArrowUp") { e.preventDefault(); steerDelta(targetDelta + 5); }
    else if (e.key === "ArrowLeft" || e.key === "ArrowDown") { e.preventDefault(); steerDelta(targetDelta - 5); }
    else if (e.key === "Home") { e.preventDefault(); steerDelta(DELTA_MIN); }
    else if (e.key === "End") { e.preventDefault(); steerDelta(DELTA_MAX); }
    else if (e.key === "0") { e.preventDefault(); steerDelta(0); }
    else if (e.key === "1") { e.preventDefault(); selectMode(0); }
    else if (e.key === "2") { e.preventDefault(); selectMode(1); }
    else if (e.key === "3") { e.preventDefault(); selectMode(2); }
  };

  stage.addEventListener("pointermove", onPointerMove);
  stage.addEventListener("pointerdown", onPointerDown);
  stage.addEventListener("pointerup", onPointerUp);
  stage.addEventListener("pointercancel", onPointerUp);
  stage.addEventListener("keydown", onKeyDown);

  modeBtns.forEach((btn, idx) => {
    btn.addEventListener("click", () => selectMode(idx));
  });
  sliderEl?.addEventListener("input", () => {
    steerDelta( Number(sliderEl.value) );
  });

  const io = new IntersectionObserver(
    (entries) => {
      visible = entries[entries.length - 1].isIntersecting;
      if (visible) kick();
    },
    { rootMargin: "120px 0px" },
  );
  io.observe(rootEl);

  renderFrame();
  kick();

  return {
    setTheme: applyTheme,
    setLang: applyLang,
    setMode: (idx) => selectMode(idx),
    setDeflection: (deg) => steerDelta(deg),
    getState: () => computeRigState(curDelta, modeIdx),
    destroy() {
      cancelAnimationFrame(frame);
      clearTimeout(idleTimer);
      io.disconnect();
    },
  };
}


export { PAYLOAD_MODES, computeRigState, formatReadout };

export function mountHilRigAnatomy(containerEl, options = {}) {
  if (!containerEl) throw new Error("mountHilRigAnatomy: containerEl is required");
  return createHilController(containerEl, {
    theme: options.theme ?? "light",
    lang: options.lang ?? "tr",
  });
}
export default mountHilRigAnatomy;
